/**
 * Registry for the lookup that answers "which plan is this org on right now".
 *
 * `lib/` cannot reach into the database layer, so the organization repository
 * registers the lookup here when it loads; plan-aware helpers such as the rate
 * limiter ask this module instead of caching a plan of their own.
 */
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Resolves an org's current plan; `null` when the org is unknown. */
export type PlanResolver = (orgId: OrgId) => Promise<PlanId | null>;

let planResolver: PlanResolver | null = null;

export function setPlanResolver(resolver: PlanResolver | null): void {
  planResolver = resolver;
}

/** The org's current plan, or `null` when no resolver is registered or the org is unknown. */
export async function resolveOrgPlan(orgId: OrgId): Promise<PlanId | null> {
  if (planResolver === null) return null;
  try {
    return await planResolver(orgId);
  } catch {
    return null;
  }
}
EOF
